// Demo account data, including 30 days of call history generated by the routing engine.
import { routeCall } from './routing';
import { makeLog, pickNumber, pickOutcome, randomCaller } from './simulate';
import { DAY, rand, startOfDay, uid } from '../utils';

const campaignSeed = now => [
  { id: 'c1', name: 'Search ads — Sales', status: 'Active', dailyCap: 0, note: 'Google and Bing search ads', createdAt: now - 60 * DAY },
  { id: 'c2', name: 'UK support line', status: 'Active', dailyCap: 0, note: '', createdAt: now - 45 * DAY },
  { id: 'c3', name: 'TV spot — toll-free', status: 'Active', dailyCap: 10, note: 'Number shown in the evening TV ad', createdAt: now - 35 * DAY },
  { id: 'c4', name: 'Spring promo', status: 'Paused', dailyCap: 50, note: 'Starts next month. Attach a number before switching on.', createdAt: now - 2 * DAY },
];
const ANY_TIME = { enabled: false, days: [0, 1, 2, 3, 4, 5, 6], start: '09:00', end: '18:00' };
const tgt = (destinationId, weight = 1) => ({ destinationId, weight });
const planSeed = now => [
  {
    id: 'p1', name: 'Sales — smart routing', campaignId: 'c1', status: 'Live', updatedAt: now - 6 * DAY,
    description: 'East-coast callers go straight to the sales desk; the rest are split 3:1 in office hours.',
    paths: [
      { id: 'p1a', name: 'Area code 2xx', prefix: '+1 2', hours: ANY_TIME, dailyCap: 0, strategy: 'Priority', targets: [tgt('d1'), tgt('d2')], ringTimeout: 20 },
      { id: 'p1b', name: 'Office hours', prefix: '', hours: { enabled: true, days: [1, 2, 3, 4, 5], start: '09:00', end: '18:00' }, dailyCap: 0, strategy: 'Round robin', targets: [tgt('d1', 3), tgt('d2', 1)], ringTimeout: 20 },
      { id: 'p1c', name: 'Everything else', prefix: '', hours: ANY_TIME, dailyCap: 0, strategy: 'Priority', targets: [tgt('d4')], ringTimeout: 25 },
    ],
  },
  {
    id: 'p2', name: 'TV spot — evening overflow', campaignId: 'c3', status: 'Draft', updatedAt: now - DAY,
    description: 'Draft: ring support and the answering service together while the ad airs.',
    paths: [
      { id: 'p2a', name: 'While the ad airs', prefix: '', hours: { enabled: true, days: [0, 1, 2, 3, 4, 5, 6], start: '19:00', end: '22:00' }, dailyCap: 6, strategy: 'Simultaneous', targets: [tgt('d3'), tgt('d4')], ringTimeout: 30 },
      { id: 'p2b', name: 'Default', prefix: '', hours: ANY_TIME, dailyCap: 0, strategy: 'Priority', targets: [tgt('d3')], ringTimeout: 30 },
    ],
  },
];
const NUMBER_CAMPAIGN = { n1: 'c1', n4: 'c1', n2: 'c2', n3: 'c3' };

/** Brings data saved by an older version up to date (adds campaigns and routing plans). */
export function migrate(db) {
  if (db.settings?.company === 'My Company') db = { ...db, settings: { ...db.settings, company: 'Micro AV' } };
  db = addCampaigns(db);
  if (db.plans) return db;
  const destIds = new Set(db.destinations.map(d => d.id));
  const campIds = new Set(db.campaigns.map(c => c.id));
  const plans = planSeed(Date.now())
    .filter(p => campIds.has(p.campaignId))
    .map(p => ({ ...p, paths: p.paths.map(x => ({ ...x, targets: x.targets.filter(y => destIds.has(y.destinationId)) })) }));
  return { ...db, plans };
}

function addCampaigns(db) {
  if (db.campaigns) return db;
  const campaigns = campaignSeed(Date.now());
  const numbers = db.numbers.map(n => ({ ...n, campaignId: n.campaignId ?? NUMBER_CAMPAIGN[n.id] ?? null }));
  const byNumber = Object.fromEntries(numbers.map(n => [n.id, campaigns.find(c => c.id === n.campaignId)]));
  const logs = db.logs.map(l => {
    const c = byNumber[l.numberId];
    return { ...l, campaignId: c?.id ?? null, campaign: c?.name ?? '—' };
  });
  return { ...db, campaigns, numbers, logs };
}

export function seed(user) {
  const now = Date.now();

  const numbers = [
    { id: 'n1', number: '+1 (212) 555-0142', label: 'Sales line', country: 'United States', type: 'Local', status: 'Active', monthlyCost: 1.5 },
    { id: 'n2', number: '+44 20 7946 0321', label: 'UK support', country: 'United Kingdom', type: 'Local', status: 'Active', monthlyCost: 2 },
    { id: 'n3', number: '+1 (800) 555-0199', label: 'Main toll-free', country: 'United States', type: 'Toll-free', status: 'Active', monthlyCost: 4 },
    { id: 'n4', number: '+1 (305) 555-0123', label: 'Miami office', country: 'United States', type: 'Local', status: 'Active', monthlyCost: 1.5 },
    { id: 'n5', number: '+49 30 901820', label: 'Berlin (old)', country: 'Germany', type: 'Local', status: 'Suspended', monthlyCost: 2.5 },
  ];

  const destinations = [
    { id: 'd1', name: 'Sales desk', target: '+1 (646) 555-0110', type: 'Phone', concurrency: 3, dailyCap: 0, status: 'Active' },
    { id: 'd2', name: 'Sales overflow', target: '+1 (917) 555-0177', type: 'Phone', concurrency: 2, dailyCap: 8, status: 'Active' },
    { id: 'd3', name: 'Support PBX', target: 'sip:support@pbx.example.com', type: 'SIP', concurrency: 5, dailyCap: 0, status: 'Active' },
    { id: 'd4', name: 'After-hours answering', target: '+1 (415) 555-0188', type: 'Phone', concurrency: 2, dailyCap: 0, status: 'Active' },
    { id: 'd5', name: 'Billing team', target: '+1 (312) 555-0164', type: 'Phone', concurrency: 1, dailyCap: 6, status: 'Active' },
  ];

  const weekdays = { enabled: true, days: [1, 2, 3, 4, 5], start: '09:00', end: '18:00', afterHoursDestinationId: 'd4' };
  const rules = [
    { id: 'r1', name: 'Sales failover', numberId: 'n1', action: 'Forward', strategy: 'Priority', targets: [{ destinationId: 'd1', weight: 1 }, { destinationId: 'd2', weight: 1 }], ringTimeout: 20, hours: weekdays, ivrId: '', enabled: true },
    { id: 'r2', name: 'UK support', numberId: 'n2', action: 'Forward', strategy: 'Simultaneous', targets: [{ destinationId: 'd3', weight: 1 }, { destinationId: 'd4', weight: 1 }], ringTimeout: 25, hours: { ...weekdays, enabled: false }, ivrId: '', enabled: true },
    { id: 'r3', name: 'Toll-free menu', numberId: 'n3', action: 'IVR', strategy: 'Priority', targets: [], ringTimeout: 30, hours: { ...weekdays, start: '08:00', end: '20:00' }, ivrId: 'i1', enabled: true },
    { id: 'r4', name: 'Miami split', numberId: 'n4', action: 'Forward', strategy: 'Round robin', targets: [{ destinationId: 'd1', weight: 2 }, { destinationId: 'd2', weight: 1 }], ringTimeout: 20, hours: { ...weekdays, enabled: false }, ivrId: '', enabled: true },
  ];

  const ivrs = [{
    id: 'i1',
    name: 'Main menu',
    greeting: 'Thanks for calling. Press 1 for sales, 2 for support, or 3 for billing.',
    timeout: 8,
    options: [
      { key: '1', label: 'Sales', destinationId: 'd1' },
      { key: '2', label: 'Support', destinationId: 'd3' },
      { key: '3', label: 'Billing', destinationId: 'd5' },
    ],
    fallbackDestinationId: 'd3',
  }];

  const blocked = [
    { id: 'b1', number: '+1 (202) 555-0100', reason: 'Robocaller', addedAt: now - 20 * DAY },
    { id: 'b2', number: '+1 (888) 555-0147', reason: 'Spam', addedAt: now - 9 * DAY },
    { id: 'b3', number: '+1 (561) 555-0192', reason: 'Abusive caller', addedAt: now - 2 * DAY },
  ];

  const settings = {
    company: 'Micro AV',
    timezone: 'UTC',
    notifyEmail: user || '',
    notifyMissed: true,
    lowBalance: 25,
    simulate: true,
    apiKey: `mav_live_${uid()}${uid()}${uid()}`,
  };

  const ratePerMin = 0.02;
  const campaigns = campaignSeed(now);
  numbers.forEach(n => { n.campaignId = NUMBER_CAMPAIGN[n.id] ?? null; });

  const plans = planSeed(now);

  const db = { campaigns, plans, numbers, destinations, rules, ivrs, blocked, logs: [], settings, billing: { balance: 0, ratePerMin, transactions: [] }, notifications: [] };

  // 30 days of history, oldest first so daily caps are evaluated correctly.
  const logs = [];
  let t = startOfDay(now) - 29 * DAY;
  while (true) {
    t += (10 + rand(70)) * 60000;
    if (t > now - 2 * 60000) break;
    const number = pickNumber(db);
    const from = randomCaller(db);
    const route = routeCall({ ...db, logs }, [], { from, numberId: number.id, at: t, key: String(1 + rand(4)) });
    let status = route.status;
    let duration = 0;
    if (status === 'Routed') {
      status = pickOutcome();
      if (status === 'Answered') duration = 20 + rand(880);
    }
    logs.push(makeLog({ time: t, from, number, route, status, duration, rate: ratePerMin }));
  }
  db.logs = logs.reverse();

  const rental = numbers.reduce((a, n) => a + n.monthlyCost, 0);
  const transactions = [
    { id: uid(), time: now - 28 * DAY, type: 'Top-up', note: 'Card ending 4242', amount: 200 },
    { id: uid(), time: now - 28 * DAY + 60000, type: 'Number rental', note: `${numbers.length} numbers`, amount: -rental },
    { id: uid(), time: now - 14 * DAY, type: 'Top-up', note: 'Card ending 4242', amount: 150 },
    { id: uid(), time: now - 3 * DAY, type: 'Top-up', note: 'Bank transfer', amount: 100 },
  ].reverse();
  const usage = db.logs.reduce((a, l) => a + l.cost, 0);
  db.billing = { balance: +(transactions.reduce((a, x) => a + x.amount, 0) - usage).toFixed(2), ratePerMin, transactions };

  db.notifications = [
    { id: uid(), time: now - 40 * 60000, title: 'Daily cap reached', body: 'Sales overflow hit its cap of 8 calls', link: '/destinations', read: false },
    { id: uid(), time: now - 3 * DAY, title: 'Funds added', body: '$100.00 added to your balance', link: '/billing', read: true },
    { id: uid(), time: now - 5 * DAY, title: 'Number suspended', body: '+49 30 901820 was suspended', link: '/numbers', read: true },
  ];

  return db;
}
